import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ci/ciag3.md","filePath":"lezioni/c_analisi/ci/ciag3.md"}`),a={name:`lezioni/c_analisi/ci/ciag3.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>Disegnare approssimativamente il grafico per la funzione: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>x</mi><mi>sin</mi><mo>⁡</mo><mi>x</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y = x \\sin x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mord mathnormal" style="color:red;">x</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">x</span></span></span></span></p><p>Il campo di esistenza è tutto l&#39;asse reale: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mtext>C.E.\xA0</mtext><mo stretchy="false">{</mo><mi>x</mi><mo>∈</mo><mi mathvariant="double-struck">R</mi><mo stretchy="false">}</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{C.E. } \\{x \\in \\mathbb{R}\\}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">C.E.\xA0</span></span><span class="mopen" style="color:red;">{</span><span class="mord mathnormal" style="color:red;">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb" style="color:red;">R</span><span class="mclose" style="color:red;">}</span></span></span></span></p><p>Scompongo la funzione: posso considerarla prodotto di due funzioni.</p><p>La prima: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>x</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y = x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="color:red;">x</span></span></span></span> è la bisettrice del primo e terzo quadrante.</p><p>La seconda: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>sin</mi><mo>⁡</mo><mi>x</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y = \\sin x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">x</span></span></span></span> è la sinusoide.</p><p>Ora la mia funzione di partenza sarà il prodotto delle funzioni parziali: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>x</mi><mo>⋅</mo><mi>sin</mi><mo>⁡</mo><mi>x</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y = x \\cdot \\sin x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord mathnormal" style="color:red;">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">x</span></span></span></span> cioè basterà che punto per punto intuitivamente io faccia il prodotto dei valori che hanno le ordinate delle due funzioni parziali.</p><p>In verde le due funzioni componenti. In rosso la loro funzione prodotto.</p><hr><blockquote><p>Si potrebbe anche dire che la funzione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>y</mi><mo>=</mo><mi>x</mi><mi>sin</mi><mo>⁡</mo><mi>x</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{y = x \\sin x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mord mathnormal" style="color:red;">x</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="color:red;">x</span></span></span></span> è una funzione pari perché è il prodotto di due funzioni dispari (meno per meno dà più).</p><p>Sapresti dimostrare che il prodotto di due funzioni dispari è una funzione pari?</p></blockquote>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};